class LighterClient(_Client):
    def __init__(self, *, origin=None, api_key=None, api_secret=None, signer=None):
        super().__init__(origin=origin, api_key=api_key, api_secret=api_secret)
        self._signer = signer

    @property
    def authenticated(self):
        self._require_open()
        return bool(self._signer)

    async def account(self, request=None, *, params=None, account_index=None, l1_address=None) -> Lighter.Accounts:
        return await execute("lighter", "account", _args.lighter_account(request, params, account_index, l1_address), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def active_orders(self, request=None, *, params=None, market_id=None) -> Lighter.Orders:
        return await execute("lighter", "active_orders", _args.fields(request, params, market_id=market_id), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def next_nonce(self, account_index=None, api_key_index=None, *, request=None, params=None) -> Lighter.NextNonce:
        return await execute("lighter", "next_nonce", _args.identifier('account_index', account_index, request, params, api_key_index=api_key_index), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def order_book_orders(self, market_id=None, *, request=None, params=None, limit=None) -> Lighter.OrderBookOrders:
        return await execute("lighter", "order_book_orders", _args.identifier('market_id', market_id, request, params, limit=50 if limit is None and isinstance(market_id, (str, int)) else limit), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def order_books(self, request=None, *, params=None, market_id=None) -> Lighter.OrderBooks:
        return await execute("lighter", "order_books", _args.fields(request, params, market_id=market_id), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def recent_trades(self, market_id=None, *, request=None, params=None, limit=None) -> Lighter.Trades:
        return await execute("lighter", "recent_trades", _args.identifier('market_id', market_id, request, params, limit=50 if limit is None and isinstance(market_id, (str, int)) else limit), origin=self._origin, api_key=self._api_key, api_secret=self._api_secret, auth=self._signer)

    async def create_order(self, request=None, options=None, *, order=None, expired_at=None, attributes=None):
        return await execute('lighter','create_order',_args.lighter_order(request, order, options, expired_at, attributes),origin=self._origin,auth=self._signer)

    async def cancel_order(self, request=None, options=None, *, order=None, expired_at=None, attributes=None):
        return await execute('lighter','cancel_order',_args.lighter_order(request, order, options, expired_at, attributes),origin=self._origin,auth=self._signer)

    async def auth_token(self, deadline):
        return await execute('lighter','auth_token',{'deadline': deadline},origin=self._origin,auth=self._signer)

    async def resync_nonce(self):
        return await execute('lighter','resync_nonce',{},origin=self._origin,auth=self._signer)

    async def prepare_transaction(self, kind, order, options, nonce):
        return await execute('lighter','prepare_transaction',{'kind': kind, 'order': order, 'options': options, 'nonce': nonce},origin=self._origin,auth=self._signer)

    async def subscribe_order_book(self, market_id, *, endpoint=None):
        return await self.subscribe({'channel':'order_book','market_id':market_id},endpoint=endpoint)

    async def subscribe_trades(self, market_id, *, endpoint=None):
        return await self.subscribe({'channel':'trade','market_id':market_id},endpoint=endpoint)

    async def subscribe_account(self, account_index, *, endpoint=None):
        return await self.subscribe({'channel':'account_all','account_index':account_index},endpoint=endpoint)

    async def subscribe_account_orders(self, *, endpoint=None):
        return await self.subscribe({'channel':'account_all_orders'},endpoint=endpoint)

    async def subscribe(self, specification=None, *, params=None, endpoint=None):
        params = _request_params(specification, params)
        return await _open_stream('lighter', 'subscribe', params, self._origin if endpoint is None else endpoint,self._api_key,self._api_secret, auth=self._signer)


