    async def open_rpc(self, *, endpoint=None, capacity=128, timeout_ms=10000):
        return await _open_stream('paradex','open_rpc',dict(capacity=capacity,timeout_ms=timeout_ms),endpoint or self._origin,self._api_key,self._api_secret,self._bearer)

    def _authentication(self, operation, **params):
        return _call(50, operation=operation, origin=self._origin, auth=self._bearer, params=params)

    async def block_signature(self, nonce, expiration, trades, parent=None):
        return self._authentication('block_signature',nonce=nonce,expiration=expiration,trades=trades,parent=parent)

    def onboarding_typed_data(self):
        return self._authentication('onboarding_typed_data')

    def evm_account_address(self, address, class_hash):
        return self._authentication('evm_account_address', address=address, class_hash=class_hash)

    async def sign_siwe(self, statement, nonce, issued_at, expiration=None):
        return self._authentication('sign_siwe', statement=statement, nonce=nonce, issued_at=issued_at, expiration=expiration)

    def set_token(self, token, *, read_only=True):
        self._authentication('validate_token', token=token)
        self._bearer = {**(self._bearer or {}), 'token':token, 'read_only':read_only}

